# Generated by scripts/ci/export_plugin_contract.py from backend/platform/agent_core/skills/plugin_contract.py; never edit it by hand.
# Published with the saphion-plugins repository beside beacon-plugin-contract.json.
"""The Beacon plugin contract's one checker: what a plugin's skills may say about Beacon's tools, and how large they may be (K8a).

``contracts/beacon-plugin-contract.json`` is generated from the real offered tools (``scripts/ci/export_plugin_contract.py``): each tool a
skill may name, its closed choices, the skill bindings and the size limits. This module judges plugin files against it, and is the ONE
implementation of that judgement:

* the platform sync runs it on every plugin it is told to hold to the contract (``plugin_sources``), so a skill that names a tool Beacon
  lacks is refused by name and the plugin keeps its current version;
* the plugins repository's CI runs the generated copy (``contracts/plugin_contract.py``, this file written out beside the contract by
  the same export) on every pull request: ``python plugin_contract.py beacon-plugin-contract.json <plugin folder>...``.

Standard library only, so the copy runs anywhere with no install. Nothing here reads a file outside the plugin or runs anything.

What a ``SKILL.md`` is judged on (each refusal names the file and the word):

* its ``allowed-tools`` (the standard field): every entry is a tool Beacon is offered, and an entry written ``tool(act=edit)`` names a choice
  that tool declares;
* its text: a word shaped like a tool name that no tool has (the shape is derived from the contract's own names, as the registry guard
  ``test_a_skill_names_only_tools_the_registry_offers`` always derived it) or that is a near miss of one (``bid_respnse_read``) is refused. A
  tool mentioned in backticks or by its snake_case name, followed by ``act`` and a choice, must name a choice that tool declares
  (``document_change`` with the act ``edit``); a choice is named by backticks or by its snake_case form (a bare one-word choice is prose and is not read);
* its size: the name, description and body ceilings the contract carries, and the package's file count and bytes.

Not judged: whether a skill's prose is good, or uses a tool well (Beacon sweeps and traces), a tool named only in a way no rule above reads (a
misspelled one-word name in prose), and a skill's other fields.
"""
from __future__ import annotations

import difflib
import json
import re
import sys
from collections import Counter
from collections.abc import Iterable, Mapping
from pathlib import Path

#: The contract's own shape version: a checker refuses a contract written for another.
FORMAT = 1
#: Where a skill's own file sits in a plugin: ``skills/<name>/SKILL.md`` (or one root ``SKILL.md`` for a bare skill).
SKILL_FILE = "SKILL.md"
#: How close a word must be to a tool's name, and not be a word the tools themselves use, to be taken as that tool misspelled.
NEAR_MISS = 0.9

_FRONT = re.compile(r"\A﻿?---[ \t]*\r?\n(.*?)^---[ \t]*\r?\n?", re.M | re.S)
_FIELD = re.compile(r"^([A-Za-z0-9_.-]+):[ \t]*(.*)$")
_WORD = re.compile(r"\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b")
_TICKED = re.compile(r"`([a-z][a-z0-9]*(?:_[a-z0-9]+)+)`")
_NAME = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
_TOOL_ENTRY = re.compile(r"\s*([^\s,()]+)(?:\(([^)]*)\))?[\s,]*")
#: ``act`` as a word (backticked or bare) then its value: backticked or a bare identifier.
_ACT = re.compile(r"\bact\b`?[\s:=]*(?:`([A-Za-z_][\w]*)`|([A-Za-z_][\w]*))")
_MENTION = re.compile(r"`([A-Za-z_][\w]*)`|\b([a-z][a-z0-9]*(?:_[a-z0-9]+)+)\b")


def closed_sets(schema: object) -> dict[str, list[str]]:
    """Every property in a JSON schema that takes one of a closed set of words (``enum`` or ``const``, wherever it sits, definitions and
    the branches of a choice included), with the words. The one reading of a closed set: the export publishes it and the checker uses it."""
    found: dict[str, set[str]] = {}

    def walk(node: object) -> None:
        if isinstance(node, dict):
            properties = node.get("properties")
            if isinstance(properties, dict):
                for name, declared in properties.items():
                    if isinstance(declared, dict):
                        words = declared.get("enum", [declared["const"]] if "const" in declared else [])
                        found.setdefault(name, set()).update(word for word in words if isinstance(word, str))
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for value in node:
                walk(value)

    walk(schema)
    return {name: sorted(words) for name, words in sorted(found.items()) if words}


def property_names(schema: object) -> set[str]:
    """Every property name a JSON schema declares, wherever it sits."""
    names: set[str] = set()

    def walk(node: object) -> None:
        if isinstance(node, dict):
            properties = node.get("properties")
            if isinstance(properties, dict):
                names.update(properties)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for value in node:
                walk(value)

    walk(schema)
    return names


def unknown_tool_mentions(text: str, names: Iterable[str], known_words: Iterable[str] = (), *, near_miss: bool = True, ticked: bool = True) -> set[str]:
    """The words of ``text`` that read as a tool's name but that no tool has.

    A word is one when it is snake_case with its first part the family of at least three tool names (``file_``, ``app_``) and its last part
    the end of one, or when it is a near miss of a tool name, or when it is written in backticks with such a first part and no tool, input or
    choice by that name: a tool renamed or retired (``record_structure`` once ``record_fields`` replaced it) or an identifier the model no longer
    sees (``file_id`` once a file is shown by its ``continuation_ref``). A word of ``known_words`` (an input or a choice some tool declares) is never
    one, so ``record_class`` and ``from_questionnaire`` are not taken for a misspelled tool. ``near_miss=False`` judges the shape alone, and ``ticked=False`` leaves out the backticked names (a caller that has no ``known_words`` to give)."""
    names = set(names)
    known = set(known_words)
    heads = {head for head, count in Counter(name.split("_")[0] for name in names if "_" in name).items() if count >= 3}
    tails = {name.rsplit("_", 1)[1] for name in names if "_" in name}
    ordered = sorted(names)
    found = set()
    for word in _WORD.findall(text):
        if word in names or word in known:
            continue
        shaped = word.split("_")[0] in heads and word.rsplit("_", 1)[1] in tails
        if shaped or (near_miss and difflib.get_close_matches(word, ordered, n=1, cutoff=NEAR_MISS)):
            found.add(word)
    for word in _TICKED.findall(text) if ticked else ():
        if word not in names and word not in known and word.split("_")[0] in heads:
            found.add(word)
    return found


def load_contract(path: str | Path) -> dict:
    """The contract, read and shape-checked; ``ValueError`` says what is wrong."""
    contract = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(contract, dict) or contract.get("format") != FORMAT:
        raise ValueError(f"{path}: not a Beacon plugin contract of format {FORMAT}.")
    return contract


def _frontmatter(text: str) -> tuple[dict[str, str], str] | None:
    """The top-level fields of a SKILL.md's frontmatter as text, and the body. A field with a nested value reads as its raw text."""
    match = _FRONT.match(text)
    if not match:
        return None
    fields: dict[str, str] = {}
    lines = match.group(1).splitlines()
    index = 0
    while index < len(lines):
        field = _FIELD.match(lines[index])
        index += 1
        if not field:
            continue
        key, value = field.group(1), field.group(2).strip()
        block = []
        while index < len(lines) and (not lines[index].strip() or lines[index][:1] in (" ", "\t")):
            block.append(lines[index].strip())
            index += 1
        if value in ("|", ">", "|-", ">-", "") and block:
            value = " ".join(part for part in block if part)
        elif value[:1] == '"':
            try:
                value = json.loads(value)
            except ValueError:
                value = value.strip('"')
        elif value[:1] == "'":
            value = value.strip("'").replace("''", "'")
        fields[key] = value
    return fields, text[match.end():]


def _skill_files(files: Mapping[str, bytes]) -> list[str]:
    return sorted(path for path in files if path == SKILL_FILE
                  or (path.startswith("skills/") and path.endswith("/" + SKILL_FILE) and path.count("/") == 2))


def _allowed_tools(where: str, value: str, tools: Mapping[str, Mapping]) -> list[str]:
    refused = []
    position = 0
    while position < len(value):
        entry = _TOOL_ENTRY.match(value, position)
        if not entry or entry.end() == position:
            refused.append(f"{where}: allowed-tools cannot be read at {value[position:position + 30]!r}.")
            break
        position = entry.end()
        name, specifier = entry.group(1), entry.group(2)
        if name not in tools:
            near = difflib.get_close_matches(name, sorted(tools), n=1, cutoff=0.6)
            refused.append(f"{where}: allowed-tools names {name}, which is not a tool Beacon is offered" + (f" (did you mean {near[0]}?)" if near else "") + ".")
            continue
        for part in (piece for piece in (specifier or "").split(",") if piece.strip()):
            key, equals, wanted = part.strip().partition("=")
            wanted = wanted.strip().strip("`'\"")
            choices = tools[name].get("choices", {}).get(key.strip())
            if not equals or choices is None:
                refused.append(f"{where}: allowed-tools names {name}({part.strip()}), but {name} has no choice called {key.strip()!r}.")
            elif wanted not in choices:
                refused.append(f"{where}: allowed-tools names {name}({key.strip()}={wanted}), but {key.strip()} is one of {', '.join(choices)}.")
    return refused


def _act_choices(where: str, body: str, tools: Mapping[str, Mapping], properties: Iterable[str]) -> list[str]:
    """Each ``act`` a paragraph names after a tool it mentions is one that tool declares (the nearest tool before it, in the same paragraph)."""
    refused = []
    for paragraph in re.split(r"\n\s*\n", body):
        mentions = [(match.start(), match.group(1) or match.group(2)) for match in _MENTION.finditer(paragraph)
                    if (match.group(1) or match.group(2)) in tools]
        for act in _ACT.finditer(paragraph):
            tool = next((name for at, name in reversed(mentions) if at < act.start()), None)
            if tool is None:
                continue
            backticked = act.group(1) is not None
            value = act.group(1) or act.group(2)
            for prop in properties:
                declared = tools[tool].get("choices", {}).get(prop)
                if declared is None or value in declared:
                    continue
                # A bare word after "act" is a choice only when it is snake_case ("the act from_questionnaire"); "act on" is prose.
                if backticked or "_" in value:
                    refused.append(f"{where}: {tool} with {prop} {value}, but {tool}'s {prop} is one of {', '.join(declared)}.")
    return refused


def vocabulary(contract: Mapping) -> set[str]:
    """The words the tools themselves use: every input name and every choice. A skill may say them without naming a tool."""
    tools = contract["tools"]
    return {word for tool in tools.values() for word in (*property_names(tool.get("schema", {})), *tool.get("choices", {}),
                                                         *(w for words in tool.get("choices", {}).values() for w in words))}


def check_skill(where: str, text: str, contract: Mapping, known: set[str] | None = None) -> list[str]:
    """One SKILL.md's refusals (each a sentence naming ``where`` and the word); empty when it is within the contract. ``known`` is
    ``vocabulary(contract)``, passed when many skills are judged."""
    tools, ceilings = contract["tools"], contract["ceilings"]
    parsed = _frontmatter(text)
    if parsed is None:
        return [f"{where}: it has no frontmatter with a name and a description."]
    fields, body = parsed
    refused = []
    name, description = fields.get("name", ""), fields.get("description", "")
    if not _NAME.match(name) or len(name) > ceilings["skill_name_characters"]:
        refused.append(f"{where}: name {name!r} must be lowercase letters, numbers and single hyphens, at most {ceilings['skill_name_characters']} characters.")
    if not description or len(description) > ceilings["skill_description_characters"]:
        refused.append(f"{where}: its description is {len(description)} characters; it needs one of at most {ceilings['skill_description_characters']}.")
    if not body.strip() or len(body) > ceilings["skill_body_characters"]:
        refused.append(f"{where}: its body is {len(body):,} characters; a skill's body holds 1 to {ceilings['skill_body_characters']:,}.")
    refused += _allowed_tools(where, fields.get("allowed-tools", ""), tools)
    known = vocabulary(contract) if known is None else known
    refused += [f"{where}: it names {word}, which is not a tool Beacon is offered" + "".join(
                f" (did you mean {near[0]}?)" for near in [difflib.get_close_matches(word, sorted(tools), n=1, cutoff=0.6)] if near) + "."
                for word in sorted(unknown_tool_mentions(body, tools, known))]
    refused += _act_choices(where, body, tools, contract.get("choice_properties", ()))
    return refused


def check_plugin(files: Mapping[str, bytes], contract: Mapping, *, label: str = "") -> list[str]:
    """Every refusal for a plugin's files (path to bytes, as the package holds them); empty when it is within the contract."""
    prefix = f"{label}/" if label else ""
    ceilings = contract["ceilings"]
    refused, known = [], vocabulary(contract)
    if len(files) > ceilings["package_files"]:
        refused.append(f"{label or 'the plugin'}: it holds {len(files)} files; at most {ceilings['package_files']}.")
    total = sum(len(data) for data in files.values())
    if total > ceilings["package_bytes"]:
        refused.append(f"{label or 'the plugin'}: it holds {total:,} bytes; at most {ceilings['package_bytes']:,}.")
    for path in _skill_files(files):
        try:
            text = files[path].decode("utf-8")
        except UnicodeError:
            refused.append(f"{prefix}{path}: it is not UTF-8 text.")
            continue
        refused += check_skill(f"{prefix}{path}", text, contract, known)
    return refused


def _folder_files(folder: Path) -> dict[str, bytes]:
    return {path.relative_to(folder).as_posix(): path.read_bytes() for path in sorted(folder.rglob("*")) if path.is_file()}


def main(argv: list[str]) -> int:
    """``plugin_contract.py <contract.json> <plugin folder>...``: print each refusal; exit 1 when there is one."""
    if len(argv) < 2:
        print("usage: plugin_contract.py <beacon-plugin-contract.json> <plugin folder>...", file=sys.stderr)
        return 2
    contract = load_contract(argv[0])
    refused = []
    for folder in map(Path, argv[1:]):
        refused += check_plugin(_folder_files(folder), contract, label=folder.name)
    for line in refused:
        print(line)
    return 1 if refused else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
